final_sql:
SELECT MAX(f.`Percent (%) Eligible Free (Ages 5-17)`)
FROM satscores s JOIN frpm f ON s.cds = f.CDSCode
WHERE s.NumTstTakr > 0 AND CAST(s.NumGE1500 AS REAL) / s.NumTstTakr > 0.3;

SELECT
  (SELECT COUNT(*) FROM gasstations WHERE Country = 'CZE' AND Segment = 'Discount')
  - (SELECT COUNT(*) FROM gasstations WHERE Country = 'SVK' AND Segment = 'Discount') AS Difference;

SELECT CASE WHEN ClosedDate IS NULL AND AcceptedAnswerId IS NOT NULL THEN 'YES' ELSE 'NO' END
FROM posts
WHERE Id = (SELECT PostId FROM comments WHERE UserId = 23853 AND CreationDate = '2013-07-12 09:08:18.0');

SELECT c.Segment
FROM transactions_1k t JOIN customers c ON c.CustomerID = t.CustomerID
WHERE t.Date = '2012-08-23' AND t.Time = '21:20:00';

SELECT 100.0 * COUNT(DISTINCT c.uuid) / (SELECT COUNT(*) FROM cards WHERE isStorySpotlight = 1)
FROM cards c JOIN foreign_data f ON f.uuid = c.uuid
WHERE c.isStorySpotlight = 1 AND f.language = 'French';

SELECT 100.0 * SUM(CASE WHEN Consumption > 528.3 THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM yearmonth
WHERE Date = '201202';

SELECT
  (SELECT COUNT(*) FROM votes WHERE strftime('%Y', CreationDate) = '2010') * 1.0 /
  (SELECT COUNT(*) FROM votes WHERE strftime('%Y', CreationDate) = '2011') AS ratio_2010_2011;

SELECT t.CustomerID, SUM(t.Amount*t.Price)/SUM(t.Amount) AS avg_unit_price, c.Currency
FROM transactions_1k t JOIN customers c ON t.CustomerID=c.CustomerID
GROUP BY t.CustomerID ORDER BY SUM(t.Amount*t.Price) DESC LIMIT 1;

SELECT 100.0 * SUM(CASE WHEN strftime('%Y', p.CreaionDate) = '2011' AND u.Reputation > 1000 THEN 1 ELSE 0 END) / COUNT(*) AS pct
FROM posts p
LEFT JOIN users u ON p.OwnerUserId = u.Id;

SELECT SUM(f.`Enrollment (Ages 5-17)`)
FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode
WHERE s.City = 'Fremont' AND s.SOCType = 'State Special Schools';

SELECT 100.0 *
  (SELECT COUNT(DISTINCT c.uuid) FROM cards c JOIN foreign_data f ON f.uuid = c.uuid WHERE c.power IS NULL AND f.language = 'French')
  / (SELECT COUNT(*) FROM cards WHERE power IS NULL) AS percentage;

SELECT 1.0 * SUM(CASE WHEN isTextless = 1 THEN 1 ELSE 0 END) / COUNT(*) AS proportion
FROM cards
WHERE layout = 'normal';

SELECT 100.0 * SUM(CASE WHEN status = 'C' THEN 1 ELSE 0 END) / COUNT(*) AS pct_running_no_issue
FROM loan
WHERE amount < 100000;

SELECT COUNT(CASE WHEN convertedManaCost = 7 THEN 1 END) * 100.0 / COUNT(*) AS pct
FROM cards
WHERE setCode = 'CSP';

SELECT 100.0 * SUM(CASE WHEN cardKingdomFoilId IS NOT NULL AND cardKingdomId IS NOT NULL THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM cards
WHERE setCode = 'CSP';

SELECT s.School, f.`Percent (%) Eligible FRPM (Ages 5-17)`
FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode
WHERE s.County = 'Los Angeles' AND s.GSserved = 'K-9';

SELECT (ld.overall_rating - jb.overall_rating) * 100.0 / jb.overall_rating AS pct_higher
FROM (SELECT pa.overall_rating FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Landon Donovan' AND pa.date = '2013-07-12 00:00:00') ld,
     (SELECT pa.overall_rating FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Jordan Bowery' AND pa.date = '2013-07-12 00:00:00') jb;

SELECT ROUND(100.0 * SUM(CASE WHEN gender = 'F' THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_women
FROM client
WHERE district_id IN (SELECT district_id FROM district WHERE A11 > 10000);

SELECT d.forename || ' ' || d.surname AS driver, d.nationality, MAX(ds.points) AS max_points
FROM driverStandings ds
JOIN drivers d ON ds.driverId = d.driverId
WHERE ds.driverId = (
    SELECT driverId FROM driverStandings GROUP BY driverId ORDER BY SUM(wins) DESC LIMIT 1
);

SELECT COUNT(*) AS attended_members
FROM attendance
WHERE link_to_event IN (SELECT event_id FROM event WHERE event_name = "Women's Soccer");

SELECT ROUND(100.0 * SUM(CASE WHEN alignment_id = 3 THEN 1 ELSE 0 END) / COUNT(*), 2) AS percentage_neutral,
       SUM(CASE WHEN alignment_id = 3 AND publisher_id = 13 THEN 1 ELSE 0 END) AS marvel_neutral_count
FROM superhero;

SELECT 100.0*SUM(CASE WHEN p.publisher_name='Marvel Comics' THEN 1 ELSE 0 END)/COUNT(*) AS percentage
FROM superhero s JOIN publisher p ON s.publisher_id=p.id
WHERE s.height_cm BETWEEN 150 AND 180;

SELECT m.first_name, m.last_name
FROM member m
WHERE m.position = 'Treasurer';

SELECT (MAX(res.milliseconds) - MIN(res.milliseconds)) * 100.0 / MAX(res.milliseconds) AS pct_faster
FROM results res
WHERE res.raceId = 387 AND res.milliseconds IS NOT NULL;

SELECT CASE WHEN EXISTS (
  SELECT 1 FROM attendance a
  JOIN member m ON a.link_to_member = m.member_id
  JOIN event e ON a.link_to_event = e.event_id
  WHERE m.first_name='Maya' AND m.last_name='Mclean' AND e.event_name='Women''s Soccer'
) THEN 'YES' ELSE 'NO' END AS attended;

SELECT CASE WHEN EXISTS (
  SELECT 1 FROM attendance a
  JOIN member m ON a.link_to_member = m.member_id
  JOIN event e ON a.link_to_event = e.event_id
  WHERE m.first_name = 'Maya' AND m.last_name = 'Mclean' AND e.event_name = 'Women''s Soccer'
) THEN 'YES' ELSE 'NO' END AS answer;

SELECT COUNT(*) * 100.0 / (SELECT COUNT(*) FROM superhero WHERE gender_id = 2)
FROM superhero
WHERE gender_id = 2 AND publisher_id = (SELECT id FROM publisher WHERE publisher_name = 'Marvel Comics');

SELECT 100.0 * SUM(CASE WHEN Birthday > '1930-12-31' THEN 1 ELSE 0 END) / COUNT(*) AS pct_female_born_after_1930
FROM Patient
WHERE SEX = 'F';

SELECT AVG(o) FROM (
  SELECT m.molecule_id,
         (SELECT COUNT(*) FROM atom a WHERE a.molecule_id = m.molecule_id AND a.element = 'o') AS o
  FROM (SELECT molecule_id FROM bond GROUP BY molecule_id HAVING SUM(bond_type <> '-') = 0) m
);

SELECT
  (SELECT COUNT(*) FROM superhero WHERE weight_kg IS NULL AND eye_colour_id = 7)
  - (SELECT COUNT(*) FROM superhero WHERE weight_kg IS NULL AND eye_colour_id = 1) AS diff;

SELECT CAST(SUM(b.bond_type = '-') AS REAL) / COUNT(DISTINCT m.molecule_id)
FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id
WHERE m.label = '+';

SELECT 100.0 * SUM(CASE WHEN element = 'c' THEN 1 ELSE 0 END) / COUNT(*)
FROM atom
WHERE molecule_id IN (SELECT molecule_id FROM bond WHERE bond_type = '=');

SELECT 100.0 * SUM(CASE WHEN m.label='+' THEN 1 ELSE 0 END) / COUNT(*) AS pct
FROM (SELECT DISTINCT molecule_id FROM bond WHERE bond_type='#') b
JOIN molecule m ON m.molecule_id=b.molecule_id;

SELECT COUNT(*) FROM atom WHERE molecule_id IN (
  SELECT molecule_id FROM bond WHERE bond_type = '#'
  INTERSECT
  SELECT molecule_id FROM atom WHERE element IN ('p','br')
);

SELECT COUNT(*) FROM atom WHERE molecule_id IN (
  SELECT molecule_id FROM bond WHERE bond_type = '#'
  INTERSECT
  SELECT molecule_id FROM atom WHERE element IN ('p','br')
);

SELECT CAST(SUM(atom.element = 'cl') AS REAL) * 100 / COUNT(*) AS chlorine_percentage
FROM atom
WHERE atom.molecule_id IN (SELECT molecule_id FROM bond WHERE bond_type = '-');

SELECT
  (SELECT COUNT(DISTINCT ID) FROM Laboratory WHERE PLT < 100) AS `lower_than_normal (PLT<100)`,
  (SELECT COUNT(DISTINCT ID) FROM Laboratory WHERE PLT > 400) AS `higher_than_normal (PLT>400)`;
